"use client";

import { useRef, useState } from "react";
import { CalendarDays, Check, ChevronRight, CircleUserRound, KeyRound, Plus, Trash2, X } from "lucide-react";
import { localizedJobTitle } from "./localization";

type Row = Record<string,any>;
type Form = Record<string,any>;
type EmployeeData={employees:Row[];departments:Row[];jobTitles:Row[];leaveTypes:Row[];employeeLeaveTypes:Row[]};
const localDate=(value:string,rtl:boolean)=>value?new Intl.DateTimeFormat(rtl?"ar-SA-u-nu-arab":"en-GB",{day:"numeric",month:"short",year:"numeric"}).format(new Date(`${value}T12:00:00`)):"—";
const employmentStatus=(value:string,rtl:boolean)=>({active:rtl?"نشط":"Active",probation:rtl?"تحت التجربة":"Probation",notice_period:rtl?"فترة إشعار":"Notice period",suspended:rtl?"موقوف":"Suspended"}[value]||value);
const countryLabel=(value:string,rtl:boolean)=>rtl?({"Saudi Arabia":"السعودية",Egypt:"مصر",Both:"السعودية ومصر"}[value]||value):value;

export function EmployeeDrawer({rtl,data,close,submit,initial}:{rtl:boolean;data:EmployeeData|null;close:()=>void;submit:(form:Form)=>Promise<void>;initial?:Form}){
  const [step,setStep]=useState(1), [saving,setSaving]=useState(false), [error,setError]=useState(""), [photoName,setPhotoName]=useState("");
  const photoInput=useRef<HTMLInputElement>(null);
  const [form,setForm]=useState<Form>({nameAr:"",nameEn:"",workEmail:"",fingerprintCode:"",personalPhone:"",workPhone:"",nationality:"Saudi",gender:"male",birthDate:"",identificationNumber:"",address:"",departmentId:"",jobTitleId:"",startDate:new Date().toISOString().slice(0,10),endDate:"",employmentStatus:"active",salary:"",salaryCurrency:"SAR",country:"Saudi Arabia",workLocation:"Riyadh, KSA",employmentType:"full_time",scheduleType:"fixed",workDays:"0,1,2,3,4",checkInTime:"09:00",checkOutTime:"17:00",graceMinutes:15,requiredDailyMinutes:480,leaveTypeIds:[],...(initial||{})});
  const selectedDepartment=data?.departments.find(item=>String(item.id)===String(form.departmentId));
  const structureManager=data?.employees.find(item=>Number(item.id)===Number(selectedDepartment?.manager_employee_id));
  const structureManagerName=structureManager?(rtl?(structureManager.name_ar||structureManager.name_en):(structureManager.name_en||structureManager.name_ar)):(rtl?"سيُحدد من الهيكل التنظيمي":"Assigned from the organization structure");
  const update=(key:string,value:any)=>setForm(v=>({...v,[key]:value}));
  const next=()=>{setError("");if(step===1&&(!form.nameAr||!form.nameEn||!form.workEmail)){setError(rtl?"الاسم العربي والإنجليزي وبريد العمل حقول مطلوبة":"Arabic name, English name and work email are required");return;}if(step===2&&(!form.departmentId||!form.jobTitleId||!form.startDate)){setError(rtl?"القسم والمسمى وتاريخ البداية مطلوبة":"Department, job title and start date are required");return;}if(step===3&&!(form.leaveTypeIds||[]).length){setError(rtl?"اختر نوع إجازة واحدًا على الأقل للموظف":"Select at least one leave type for the employee");return;}setStep(Math.min(4,step+1));};
  const finish=async()=>{try{setSaving(true);setError("");await submit(form);}catch(e){setError(e instanceof Error?e.message:"Unable to create employee");setSaving(false);}};
  return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label={rtl?"إغلاق النافذة":"Close"}/><aside className="drawer employee-drawer"><div className="drawer-head"><div><span className="eyebrow">{rtl?"ملف الموظف":"EMPLOYEE RECORD"}</span><h2>{rtl?"إضافة موظف جديد":"Add a new employee"}</h2><p>{rtl?"سيُنشأ الرقم الوظيفي وحساب المستخدم تلقائياً بعد الحفظ.":"An employee ID and linked user account will be created automatically."}</p></div><button className="icon-btn" onClick={close} aria-label={rtl?"إغلاق":"Close"}><X size={20}/></button></div>
  <div className="employee-steps">{[{n:1,e:"Basic",a:"البيانات الأساسية"},{n:2,e:"Employment",a:"التوظيف"},{n:3,e:"Attendance & leave",a:"الحضور والإجازات"},{n:4,e:"Review",a:"المراجعة"}].map(s=><span className={step===s.n?"active":step>s.n?"done":""} key={s.n}><b>{step>s.n?<Check size={16}/>:s.n}</b>{rtl?s.a:s.e}</span>)}</div>
  <div className="form-body">{error&&<div className="form-error">{error}</div>}
  {step===1&&<><div className="photo-upload"><CircleUserRound size={24}/><div><b>{photoName||(rtl?"الصورة الشخصية":"Employee photo")}</b><small>{rtl?"JPG أو PNG بحد أقصى ٥ م.ب":"JPG or PNG up to 5 MB"}</small></div><input ref={photoInput} className="visually-hidden" type="file" accept="image/jpeg,image/png" onChange={event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){setError(rtl?"حجم الصورة يجب ألا يتجاوز ٥ م.ب":"Photo must be 5 MB or smaller");event.target.value="";return;}setPhotoName(file.name);setError("");}}/><button className="outline" type="button" onClick={()=>photoInput.current?.click()}>{rtl?"رفع صورة":"Upload photo"}</button></div><div className="form-row"><Field label={rtl?"الاسم الكامل بالعربية *":"Arabic full name *"}><input value={form.nameAr} onChange={e=>update("nameAr",e.target.value)} dir="rtl"/></Field><Field label={rtl?"الاسم الكامل بالإنجليزية *":"English full name *"}><input value={form.nameEn} onChange={e=>update("nameEn",e.target.value)} dir="ltr"/></Field></div><Field label={rtl?"البريد الإلكتروني للعمل *":"Work email *"}><input type="email" dir="ltr" value={form.workEmail} onChange={e=>update("workEmail",e.target.value)} placeholder="name@sanad.sa"/></Field><div className="form-row"><Field label={rtl?"رمز الموظف في جهاز البصمة":"Fingerprint device code"}><input value={form.fingerprintCode} onChange={e=>update("fingerprintCode",e.target.value)}/></Field><Field label={rtl?"الجنسية":"Nationality"}><input value={form.nationality} onChange={e=>update("nationality",e.target.value)}/></Field></div><div className="form-row"><Field label={rtl?"رقم الجوال الشخصي":"Personal mobile"}><input dir="ltr" value={form.personalPhone} onChange={e=>update("personalPhone",e.target.value)}/></Field><Field label={rtl?"رقم جوال العمل":"Work mobile"}><input dir="ltr" value={form.workPhone} onChange={e=>update("workPhone",e.target.value)}/></Field></div><div className="form-row"><Field label={rtl?"الجنس":"Gender"}><select value={form.gender} onChange={e=>update("gender",e.target.value)}><option value="male">{rtl?"ذكر":"Male"}</option><option value="female">{rtl?"أنثى":"Female"}</option></select></Field><Field label={rtl?"تاريخ الميلاد":"Date of birth"}><input type="date" value={form.birthDate} onChange={e=>update("birthDate",e.target.value)}/></Field></div><Field label={rtl?"رقم الهوية الوطنية أو الإقامة":"National ID / Iqama"}><input value={form.identificationNumber} onChange={e=>update("identificationNumber",e.target.value)}/></Field><Field label={rtl?"العنوان الوطني":"Address"}><textarea value={form.address} onChange={e=>update("address",e.target.value)}/></Field></>}
  {step===2&&<>
    <div className="form-row"><Field label={rtl?"القسم *":"Department *"}><select value={form.departmentId} onChange={e=>update("departmentId",e.target.value)}><option value="">{rtl?"اختر القسم":"Select department"}</option>{data?.departments.map(d=><option value={d.id} key={d.id}>{rtl?d.name_ar:d.name_en}</option>)}</select></Field><Field label={rtl?"المسمى الوظيفي *":"Job title *"}><select value={form.jobTitleId} onChange={e=>update("jobTitleId",e.target.value)}><option value="">{rtl?"اختر المسمى الوظيفي":"Select job title"}</option>{data?.jobTitles.filter(j=>!form.departmentId||String(j.department_id)===String(form.departmentId)).map(j=><option value={j.id} key={j.id}>{localizedJobTitle(rtl,j)}</option>)}</select></Field></div>
    <div className="info-card"><CircleUserRound size={20}/><div><b>{rtl?"المدير المباشر من الهيكل التنظيمي":"Direct manager from organization structure"}</b><p>{structureManagerName}</p></div></div>
    <div className="form-row"><Field label={rtl?"تاريخ المباشرة *":"Employment start date *"}><input type="date" value={form.startDate} onChange={e=>update("startDate",e.target.value)}/></Field><Field label={rtl?"الحالة الوظيفية":"Employment status"}><select value={form.employmentStatus} onChange={e=>update("employmentStatus",e.target.value)}>{["active","probation","notice_period","suspended"].map(value=><option value={value} key={value}>{employmentStatus(value,rtl)}</option>)}</select></Field></div>
    <div className="form-row"><Field label={rtl?"الدولة":"Country"}><select value={form.country} onChange={e=>{update("country",e.target.value);update("salaryCurrency",e.target.value==="Egypt"?"EGP":"SAR");}}>{["Saudi Arabia","Egypt"].map(value=><option value={value} key={value}>{countryLabel(value,rtl)}</option>)}</select></Field><Field label={rtl?"مقر العمل":"Work location"}><input value={form.workLocation} onChange={e=>update("workLocation",e.target.value)}/></Field></div>
    <div className="form-row"><Field label={rtl?"الراتب الأساسي":"Salary"}><input type="number" min="0" value={form.salary} onChange={e=>update("salary",e.target.value)}/></Field><Field label={rtl?"العملة":"Currency"}><select value={form.salaryCurrency} onChange={e=>update("salaryCurrency",e.target.value)}><option value="SAR">{rtl?"ريال سعودي (SAR)":"Saudi riyal (SAR)"}</option><option value="EGP">{rtl?"جنيه مصري (EGP)":"Egyptian pound (EGP)"}</option></select></Field></div>
    <Field label={rtl?"نوع التوظيف":"Employment type"}><select value={form.employmentType} onChange={e=>update("employmentType",e.target.value)}><option value="full_time">{rtl?"دوام كامل":"Full time"}</option><option value="part_time">{rtl?"دوام جزئي":"Part time"}</option><option value="contract">{rtl?"عقد محدد المدة":"Fixed-term contract"}</option></select></Field>
  </>}
  {step===3&&<><Field label={rtl?"نوع جدول الحضور":"Attendance schedule type"}><select value={form.scheduleType} onChange={e=>update("scheduleType",e.target.value)}><option value="fixed">{rtl?"دوام ثابت":"Fixed schedule"}</option><option value="shift">{rtl?"نظام ورديات":"Shift schedule"}</option></select></Field><div className="form-row"><Field label={rtl?"وقت الحضور":"Check-in time"}><input type="time" value={form.checkInTime} onChange={e=>update("checkInTime",e.target.value)}/></Field><Field label={rtl?"وقت الانصراف":"Check-out time"}><input type="time" value={form.checkOutTime} onChange={e=>update("checkOutTime",e.target.value)}/></Field></div><div className="form-row"><Field label={rtl?"فترة السماح بالدقائق":"Grace period (minutes)"}><input type="number" value={form.graceMinutes} onChange={e=>update("graceMinutes",e.target.value)}/></Field><Field label={rtl?"ساعات العمل اليومية":"Required daily hours"}><input type="number" step="0.5" value={form.requiredDailyMinutes/60} onChange={e=>update("requiredDailyMinutes",Number(e.target.value)*60)}/></Field></div><Field label={rtl?"أيام العمل":"Working days"}><div className="day-selector">{(rtl?["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"]:["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]).map((d,i)=><label key={d}><input type="checkbox" defaultChecked={i<5}/><span>{d}</span></label>)}</div></Field><LeaveTypePicker rtl={rtl} rows={data?.leaveTypes??[]} selected={form.leaveTypeIds||[]} onChange={value=>update("leaveTypeIds",value)}/></>}
  {step===4&&<div className="review-card"><div className="review-person"><span className="avatar blue">{(form.nameEn||"NE").split(" ").map((x:string)=>x[0]).join("").slice(0,2)}</span><div><h3>{rtl?form.nameAr:form.nameEn}</h3><p dir="ltr">{form.workEmail}</p></div><span className="status green"><i/>{rtl?"جاهز للإنشاء":"Ready"}</span></div><div className="review-grid"><Review label={rtl?"القسم":"Department"} value={data?.departments.find(d=>String(d.id)===String(form.departmentId))?.[rtl?"name_ar":"name_en"]}/><Review label={rtl?"المسمى الوظيفي":"Job title"} value={data?.jobTitles.find(j=>String(j.id)===String(form.jobTitleId))?.[rtl?"name_ar":"name_en"]}/><Review label={rtl?"الدولة":"Country"} value={countryLabel(form.country,rtl)}/><Review label={rtl?"تاريخ المباشرة":"Start date"} value={localDate(form.startDate,rtl)}/><Review label={rtl?"جدول الدوام":"Schedule"} value={`${form.checkInTime} — ${form.checkOutTime}`}/><Review label={rtl?"أنواع الإجازات":"Leave types"} value={(form.leaveTypeIds||[]).map((id:number)=>{const item=data?.leaveTypes.find(row=>Number(row.id)===Number(id));return rtl?item?.name_ar:item?.name_en}).filter(Boolean).join("، ")}/></div><div className="account-note"><KeyRound size={20}/><div><b>{rtl?"سيتم إنشاء حساب مستخدم مرتبط":"A linked user account will be created"}</b><small>{rtl?"الدور الافتراضي: موظف، ويمكن تعديله لاحقاً.":"Initial role: Employee. You can change it later."}</small></div></div></div>}</div>
  <div className="drawer-footer"><button className="ghost" onClick={close}>{rtl?"إغلاق والمتابعة لاحقاً":"Close and continue later"}</button><span/><button className="outline" onClick={()=>step===1?close():setStep(step-1)}>{step===1?(rtl?"إلغاء":"Cancel"):(rtl?"السابق":"Back")}</button>{step<4?<button className="primary" onClick={next}>{rtl?"التالي":"Continue"}<ChevronRight size={16}/></button>:<button className="primary" disabled={saving} onClick={()=>void finish()}>{saving?(rtl?"جارٍ الإنشاء...":"Creating..."):(rtl?"إنشاء الموظف":"Create employee")}<Check size={16}/></button>}</div></aside></div>;
}

function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Review({label,value}:{label:string;value:any}){return <span><small>{label}</small><b>{value||"—"}</b></span>}
function LeaveTypePicker({rtl,rows,selected,onChange}:{rtl:boolean;rows:Row[];selected:number[];onChange:(value:number[])=>void}){
  const active=rows.filter(row=>row.status==="active"&&row.code!=="OFFICIAL"),selectedIds=selected.map(Number);
  const toggle=(id:number)=>onChange(selectedIds.includes(id)?selectedIds.filter(value=>value!==id):[...selectedIds,id]);
  return <section className="employee-leave-picker"><header><div><b>{rtl?"أنواع الإجازات المتاحة للموظف":"Employee leave types"}</b><small>{rtl?"لن تظهر في بوابة الموظف إلا الأنواع المحددة هنا":"Only selected types will appear in the employee portal"}</small></div><span>{new Intl.NumberFormat(rtl?"ar-SA-u-nu-arab":"en-GB").format(selected.length)} {rtl?"محدد":"selected"}</span></header><div>{active.map(row=>{const checked=selectedIds.includes(Number(row.id));return <label className={checked?"selected":""} key={row.id}><input type="checkbox" checked={checked} onChange={()=>toggle(Number(row.id))}/><span><b>{rtl?row.name_ar:row.name_en}</b><small>{row.code}</small></span><i><Check size={15}/></i></label>})}</div></section>;
}

export function HolidayDrawer({rtl,close,submit}:{rtl:boolean;close:()=>void;submit:(form:Form)=>Promise<void>}){
  const [form,setForm]=useState<Form>({nameEn:"",nameAr:"",holidayDate:"",country:"Both",days:1,attendanceTypes:"",recurrenceType:"once",notes:""}); const [saving,setSaving]=useState(false),[error,setError]=useState("");
  const save=async()=>{if(!form.nameEn||!form.nameAr||!form.holidayDate){setError(rtl?"الاسم والتاريخ حقول مطلوبة":"Names and date are required");return;}try{setSaving(true);await submit(form);}catch(e){setError(e instanceof Error?e.message:"Unable to save holiday");setSaving(false);}};
  return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label={rtl?"إغلاق النافذة":"Close"}/><aside className="drawer"><div className="drawer-head"><div><span className="eyebrow">{rtl?"تقويم المنشأة":"COMPANY CALENDAR"}</span><h2>{rtl?"إضافة عطلة رسمية":"Add an official holiday"}</h2><p>{rtl?"ستُحتسب العطلة تلقائياً ضمن سجلات الحضور.":"The holiday will be included automatically in attendance calculations."}</p></div><button className="icon-btn" onClick={close} aria-label={rtl?"إغلاق":"Close"}><X size={20}/></button></div><div className="form-body">{error&&<div className="form-error">{error}</div>}<Field label={rtl?"اسم العطلة بالعربية *":"Arabic name *"}><input value={form.nameAr} dir="rtl" onChange={e=>setForm({...form,nameAr:e.target.value})}/></Field><Field label={rtl?"اسم العطلة بالإنجليزية *":"English name *"}><input value={form.nameEn} dir="ltr" onChange={e=>setForm({...form,nameEn:e.target.value})}/></Field><div className="form-row"><Field label={rtl?"تاريخ العطلة *":"Date *"}><input type="date" value={form.holidayDate} onChange={e=>setForm({...form,holidayDate:e.target.value})}/></Field><Field label={rtl?"مدة العطلة بالأيام":"Number of days"}><input type="number" min="0.5" step="0.5" value={form.days} onChange={e=>setForm({...form,days:Number(e.target.value)})}/></Field></div><div className="form-row"><Field label={rtl?"الدول المشمولة":"Applies to"}><select value={form.country} onChange={e=>setForm({...form,country:e.target.value})}>{["Both","Saudi Arabia","Egypt"].map(value=><option value={value} key={value}>{countryLabel(value,rtl)}</option>)}</select></Field><Field label={rtl?"نوع التكرار":"Recurrence"}><select value={form.recurrenceType} onChange={e=>setForm({...form,recurrenceType:e.target.value})}><option value="once">{rtl?"لمرة واحدة":"One time"}</option><option value="annual">{rtl?"سنوي":"Annual"}</option></select></Field></div><Field label={rtl?"أنواع الحضور (افصل بينها بعلامة |)":"Attendance types (separate with |)"}><textarea value={form.attendanceTypes} onChange={e=>setForm({...form,attendanceTypes:e.target.value})} placeholder={rtl?"وقت ثابت مصر | وقت ثابت للمملكة":"Egypt fixed time | KSA fixed time"}/></Field><Field label={rtl?"ملاحظات داخلية":"Notes"}><textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></Field></div><div className="drawer-footer"><span/><button className="outline" onClick={close}>{rtl?"إلغاء":"Cancel"}</button><button className="primary" disabled={saving} onClick={()=>void save()}>{saving?(rtl?"جارٍ الحفظ...":"Saving..."):(rtl?"حفظ العطلة":"Save holiday")}<Check size={16}/></button></div></aside></div>;
}

function employeeForm(employee:Row):Form{return {
  employeeId:employee.id,nameAr:employee.name_ar||"",nameEn:employee.name_en||"",workEmail:employee.work_email||"",
  fingerprintCode:employee.fingerprint_code||"",personalPhone:employee.personal_phone||"",workPhone:employee.work_phone||"",
  nationality:employee.nationality||"",gender:employee.gender||"male",birthDate:employee.birth_date||"",
  identificationNumber:employee.identification_number||"",address:employee.address||"",departmentId:employee.department_id||"",
  jobTitleId:employee.job_title_id||"",startDate:employee.start_date||"",endDate:employee.end_date||"",
  employmentStatus:employee.employment_status||"active",salary:employee.salary||"",salaryCurrency:employee.salary_currency||"SAR",
  country:employee.country||"Saudi Arabia",workLocation:employee.work_location||"",employmentType:employee.employment_type||"full_time",
  scheduleType:employee.schedule_type||"fixed",workDays:employee.work_days||"0,1,2,3,4",checkInTime:employee.check_in_time||"09:00",
  checkOutTime:employee.check_out_time||"17:00",graceMinutes:employee.grace_minutes??15,requiredDailyMinutes:employee.required_daily_minutes??480,
  bankName:employee.bank_name||"",bankAccountNumber:employee.bank_account_number||"",bankIban:employee.bank_iban||"",
};}

export function EmployeeDetailsDrawer({rtl,employee,data,close,submit,startInEdit=false}:{rtl:boolean;employee:Row;data:EmployeeData|null;close:()=>void;submit:(form:Form)=>Promise<void>;startInEdit?:boolean}){
  const [editing,setEditing]=useState(startInEdit),[tab,setTab]=useState("personal"),[saving,setSaving]=useState(false),[error,setError]=useState("");
  const initialForm=()=>({...employeeForm(employee),leaveTypeIds:(data?.employeeLeaveTypes??[]).filter(row=>Number(row.employee_id)===Number(employee.id)).map(row=>Number(row.leave_type_id))});
  const [form,setForm]=useState<Form>(initialForm);
  const update=(key:string,value:any)=>setForm(current=>({...current,[key]:value}));
  const save=async()=>{if(!form.nameAr||!form.nameEn||!form.workEmail||!form.startDate){setError(rtl?"الاسم والبريد الوظيفي وتاريخ المباشرة حقول مطلوبة":"Name, work email and start date are required");return;}if(!(form.leaveTypeIds||[]).length){setError(rtl?"اختر نوع إجازة واحدًا على الأقل":"Select at least one leave type");setTab("leave");return;}try{setSaving(true);setError("");await submit(form);setEditing(false);}catch(e){setError(e instanceof Error?e.message:(rtl?"تعذر حفظ بيانات الموظف":"Unable to save employee"));}finally{setSaving(false);}};
  const department=data?.departments.find(item=>String(item.id)===String(form.departmentId));
  const job=data?.jobTitles.find(item=>String(item.id)===String(form.jobTitleId));
  const departmentChanged=String(form.departmentId)!==String(employee.department_id);
  const nextStructureManager=departmentChanged?data?.employees.find(item=>Number(item.id)===Number(department?.manager_employee_id)):data?.employees.find(item=>Number(item.id)===Number(employee.org_manager_id));
  const structureManagerName=nextStructureManager?(rtl?(nextStructureManager.name_ar||nextStructureManager.name_en):(nextStructureManager.name_en||nextStructureManager.name_ar)):(rtl?(employee.manager_name_ar||employee.manager_name):(employee.manager_name||employee.manager_name_ar))||(rtl?"غير محدد في الهيكل":"Not assigned in the structure");
  const tabs=[{id:"personal",label:rtl?"البيانات الشخصية":"Personal"},{id:"employment",label:rtl?"البيانات الوظيفية":"Employment"},{id:"attendance",label:rtl?"الحضور والدوام":"Attendance"},{id:"leave",label:rtl?"الإجازات":"Leave"}];
  return <div className="modal-layer modal-center"><button className="modal-scrim" onClick={close} aria-label={rtl?"إغلاق ملف الموظف":"Close employee profile"}/><aside className="modal-dialog employee-profile-modal" role="dialog" aria-modal="true">
    <div className="drawer-head employee-profile-head"><AvatarBlock employee={employee}/><div><span className="eyebrow">{rtl?"ملف الموظف":"EMPLOYEE PROFILE"}</span><h2>{rtl?form.nameAr:form.nameEn}</h2><p>{employee.employee_code} · {localizedJobTitle(rtl,job,{name_en:employee.job_title_name,name_ar:employee.job_title_name_ar})}</p></div><button className="icon-btn" onClick={close} aria-label={rtl?"إغلاق":"Close"}><X size={20}/></button></div>
    <div className="profile-summary"><span><small>{rtl?"القسم":"Department"}</small><b>{rtl?(department?.name_ar||employee.department_name):(department?.name_en||employee.department_name)||"—"}</b></span><span><small>{rtl?"الحالة":"Status"}</small><b>{employmentStatus(form.employmentStatus,rtl)}</b></span><span><small>{rtl?"تاريخ المباشرة":"Start date"}</small><b>{localDate(form.startDate,rtl)}</b></span></div>
    <div className="employee-profile-tabs">{tabs.map(item=><button className={tab===item.id?"active":""} onClick={()=>setTab(item.id)} key={item.id}>{item.label}</button>)}</div>
    <div className="form-body">{error&&<div className="form-error">{error}</div>}<fieldset className="profile-fieldset" disabled={!editing}>
      {tab==="personal"&&<><div className="form-row"><Field label={rtl?"الاسم بالعربية":"Arabic name"}><input value={form.nameAr} dir="rtl" onChange={e=>update("nameAr",e.target.value)}/></Field><Field label={rtl?"الاسم بالإنجليزية":"English name"}><input value={form.nameEn} dir="ltr" onChange={e=>update("nameEn",e.target.value)}/></Field></div><Field label={rtl?"البريد الوظيفي":"Work email"}><input type="email" dir="ltr" value={form.workEmail} onChange={e=>update("workEmail",e.target.value)}/></Field><div className="form-row"><Field label={rtl?"الجوال الشخصي":"Personal mobile"}><input dir="ltr" value={form.personalPhone} onChange={e=>update("personalPhone",e.target.value)}/></Field><Field label={rtl?"جوال العمل":"Work mobile"}><input dir="ltr" value={form.workPhone} onChange={e=>update("workPhone",e.target.value)}/></Field></div><div className="form-row"><Field label={rtl?"الجنسية":"Nationality"}><input value={form.nationality} onChange={e=>update("nationality",e.target.value)}/></Field><Field label={rtl?"الجنس":"Gender"}><select value={form.gender} onChange={e=>update("gender",e.target.value)}><option value="male">{rtl?"ذكر":"Male"}</option><option value="female">{rtl?"أنثى":"Female"}</option></select></Field></div><div className="form-row"><Field label={rtl?"تاريخ الميلاد":"Date of birth"}><input type="date" value={form.birthDate} onChange={e=>update("birthDate",e.target.value)}/></Field><Field label={rtl?"رقم الهوية أو الإقامة":"National ID / Iqama"}><input value={form.identificationNumber} onChange={e=>update("identificationNumber",e.target.value)}/></Field></div><Field label={rtl?"العنوان":"Address"}><textarea value={form.address} onChange={e=>update("address",e.target.value)}/></Field></>}
      {tab==="employment"&&<><div className="form-row"><Field label={rtl?"القسم":"Department"}><select value={form.departmentId} onChange={e=>update("departmentId",e.target.value)}>{data?.departments.map(item=><option value={item.id} key={item.id}>{rtl?item.name_ar:item.name_en}</option>)}</select></Field><Field label={rtl?"المسمى الوظيفي":"Job title"}><select value={form.jobTitleId} onChange={e=>update("jobTitleId",e.target.value)}>{data?.jobTitles.filter(item=>!form.departmentId||String(item.department_id)===String(form.departmentId)).map(item=><option value={item.id} key={item.id}>{localizedJobTitle(rtl,item)}</option>)}</select></Field></div><div className="info-card"><CircleUserRound size={20}/><div><b>{rtl?"المدير المباشر من الهيكل التنظيمي":"Direct manager from organization structure"}</b><p>{structureManagerName}</p></div></div><div className="form-row"><Field label={rtl?"تاريخ المباشرة":"Start date"}><input type="date" value={form.startDate} onChange={e=>update("startDate",e.target.value)}/></Field><Field label={rtl?"تاريخ انتهاء العقد":"End date"}><input type="date" value={form.endDate} onChange={e=>update("endDate",e.target.value)}/></Field></div><div className="form-row"><Field label={rtl?"الحالة الوظيفية":"Employment status"}><select value={form.employmentStatus} onChange={e=>update("employmentStatus",e.target.value)}>{["active","probation","notice_period","suspended"].map(value=><option value={value} key={value}>{employmentStatus(value,rtl)}</option>)}</select></Field><Field label={rtl?"نوع التوظيف":"Employment type"}><select value={form.employmentType} onChange={e=>update("employmentType",e.target.value)}><option value="full_time">{rtl?"دوام كامل":"Full time"}</option><option value="part_time">{rtl?"دوام جزئي":"Part time"}</option><option value="contract">{rtl?"عقد محدد المدة":"Fixed-term contract"}</option></select></Field></div><div className="form-row"><Field label={rtl?"الدولة":"Country"}><select value={form.country} onChange={e=>update("country",e.target.value)}>{["Saudi Arabia","Egypt"].map(value=><option value={value} key={value}>{countryLabel(value,rtl)}</option>)}</select></Field><Field label={rtl?"مقر العمل":"Work location"}><input value={form.workLocation} onChange={e=>update("workLocation",e.target.value)}/></Field></div><div className="form-row"><Field label={rtl?"الراتب الأساسي":"Salary"}><input type="number" min="0" value={form.salary} onChange={e=>update("salary",e.target.value)}/></Field><Field label={rtl?"العملة":"Currency"}><select value={form.salaryCurrency} onChange={e=>update("salaryCurrency",e.target.value)}><option value="SAR">SAR</option><option value="EGP">EGP</option></select></Field></div><div className="form-row"><Field label={rtl?"اسم البنك":"Bank name"}><input value={form.bankName} onChange={e=>update("bankName",e.target.value)}/></Field><Field label={rtl?"رقم الحساب":"Account number"}><input dir="ltr" value={form.bankAccountNumber} onChange={e=>update("bankAccountNumber",e.target.value)}/></Field></div><Field label={rtl?"رقم الآيبان (IBAN)":"IBAN"}><input dir="ltr" value={form.bankIban} onChange={e=>update("bankIban",e.target.value)}/></Field></>}
      {tab==="attendance"&&<><div className="form-row"><Field label={rtl?"نوع الجدول":"Schedule type"}><select value={form.scheduleType} onChange={e=>update("scheduleType",e.target.value)}><option value="fixed">{rtl?"دوام ثابت":"Fixed"}</option><option value="shift">{rtl?"ورديات":"Shift"}</option></select></Field><Field label={rtl?"رمز جهاز البصمة":"Fingerprint code"}><input value={form.fingerprintCode} onChange={e=>update("fingerprintCode",e.target.value)}/></Field></div><div className="form-row"><Field label={rtl?"وقت الحضور":"Check-in"}><input type="time" value={form.checkInTime} onChange={e=>update("checkInTime",e.target.value)}/></Field><Field label={rtl?"وقت الانصراف":"Check-out"}><input type="time" value={form.checkOutTime} onChange={e=>update("checkOutTime",e.target.value)}/></Field></div><div className="form-row"><Field label={rtl?"فترة السماح بالدقائق":"Grace period (minutes)"}><input type="number" min="0" value={form.graceMinutes} onChange={e=>update("graceMinutes",e.target.value)}/></Field><Field label={rtl?"ساعات العمل اليومية":"Required daily hours"}><input type="number" step="0.5" value={Number(form.requiredDailyMinutes)/60} onChange={e=>update("requiredDailyMinutes",Number(e.target.value)*60)}/></Field></div><Field label={rtl?"أيام العمل":"Working days"}><div className="day-selector">{(rtl?["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"]:["Sun","Mon","Tue","Wed","Thu","Fri","Sat"]).map((day,index)=>{const values=String(form.workDays).split(",");return <label key={day}><input type="checkbox" checked={values.includes(String(index))} onChange={event=>{const next=event.target.checked?[...values,String(index)]:values.filter(value=>value!==String(index));update("workDays",next.filter(Boolean).sort().join(","));}}/><span>{day}</span></label>})}</div></Field></>}
      {tab==="leave"&&<LeaveTypePicker rtl={rtl} rows={data?.leaveTypes??[]} selected={form.leaveTypeIds||[]} onChange={value=>update("leaveTypeIds",value)}/>}
    </fieldset></div>
    <div className="drawer-footer">{editing?<><button className="ghost" onClick={()=>{setForm(initialForm());setEditing(false);setError("");}}>{rtl?"إلغاء التعديلات":"Discard changes"}</button><span/><button className="primary" disabled={saving} onClick={()=>void save()}><Check size={16}/>{saving?(rtl?"جارٍ الحفظ...":"Saving..."):(rtl?"حفظ التعديلات":"Save changes")}</button></>:<><span/><button className="outline" onClick={close}>{rtl?"إغلاق":"Close"}</button><button className="primary" onClick={()=>setEditing(true)}>{rtl?"تعديل البيانات":"Edit employee"}</button></>}</div>
  </aside></div>;
}

function AvatarBlock({employee}:{employee:Row}){const initials=String(employee.name_en||"E").split(" ").map((part:string)=>part[0]).join("").slice(0,2);return <span className="profile-avatar">{initials}</span>}

export function OrganizationEntityDrawer({rtl,kind,record,departments,close,submit}:{rtl:boolean;kind:"job_title"|"department";record?:Row|null;departments:Row[];close:()=>void;submit:(form:Form)=>Promise<void>}){
  const editing=Boolean(record?.id);const [saving,setSaving]=useState(false),[error,setError]=useState("");
  const [form,setForm]=useState<Form>({nameEn:record?.name_en||"",nameAr:record?.name_ar||"",departmentId:record?.department_id||"",parentId:record?.parent_id||"",status:record?.status||"active"});
  const title=kind==="job_title"?(editing?(rtl?"تعديل المسمى الوظيفي":"Edit job title"):(rtl?"إضافة مسمى وظيفي":"Add job title")):(editing?(rtl?"تعديل القسم":"Edit department"):(rtl?"إضافة قسم":"Add department"));
  const save=async()=>{if(!String(form.nameEn).trim()||!String(form.nameAr).trim()){setError(rtl?"الاسم العربي والإنجليزي مطلوبان":"Arabic and English names are required");return;}try{setSaving(true);setError("");await submit({...form,...(kind==="job_title"?{jobTitleId:record?.id||null}:{departmentId:record?.id||null})});}catch(reason){setError(reason instanceof Error?reason.message:(rtl?"تعذر حفظ البيانات":"Unable to save changes"));setSaving(false);}};
  return <div className="modal-layer"><button className="modal-scrim" onClick={close} aria-label={rtl?"إغلاق النافذة":"Close"}/><aside className="drawer entity-drawer"><div className="drawer-head"><div><span className="eyebrow">{kind==="job_title"?(rtl?"إدارة المسميات":"JOB TITLES"):(rtl?"إدارة الأقسام":"DEPARTMENTS")}</span><h2>{title}</h2><p>{kind==="job_title"?(rtl?"أدخل اسم المسمى واربطه بالقسم المناسب.":"Name the role and link it to the appropriate department."):(rtl?"أدخل بيانات القسم وحدد تبعيته التنظيمية.":"Enter the department details and its place in the organization.")}</p></div><button className="icon-btn" onClick={close} aria-label={rtl?"إغلاق":"Close"}><X size={20}/></button></div><div className="form-body">{error&&<div className="form-error" role="alert">{error}</div>}<Field label={rtl?"الاسم بالعربية *":"Arabic name *"}><input dir="rtl" value={form.nameAr} onChange={event=>setForm(current=>({...current,nameAr:event.target.value}))}/></Field><Field label={rtl?"الاسم بالإنجليزية *":"English name *"}><input dir="ltr" value={form.nameEn} onChange={event=>setForm(current=>({...current,nameEn:event.target.value}))}/></Field>{kind==="job_title"?<Field label={rtl?"القسم":"Department"}><select value={form.departmentId} onChange={event=>setForm(current=>({...current,departmentId:event.target.value}))}><option value="">{rtl?"بدون قسم محدد":"No department"}</option>{departments.filter(item=>item.status!=="archived").map(item=><option key={item.id} value={item.id}>{rtl?item.name_ar:item.name_en}</option>)}</select></Field>:<Field label={rtl?"القسم الرئيسي":"Parent department"}><select value={form.parentId} onChange={event=>setForm(current=>({...current,parentId:event.target.value}))}><option value="">{rtl?"قسم رئيسي مستقل":"Top-level department"}</option>{departments.filter(item=>Number(item.id)!==Number(record?.id)&&item.status!=="archived").map(item=><option key={item.id} value={item.id}>{rtl?item.name_ar:item.name_en}</option>)}</select></Field>}<Field label={rtl?"الحالة":"Status"}><select value={form.status} onChange={event=>setForm(current=>({...current,status:event.target.value}))}><option value="active">{rtl?"نشط":"Active"}</option><option value="archived">{rtl?"مؤرشف":"Archived"}</option></select></Field></div><div className="drawer-footer"><span/><button className="outline" onClick={close}>{rtl?"إلغاء":"Cancel"}</button><button className="primary" disabled={saving} onClick={()=>void save()}><Check size={16}/>{saving?(rtl?"جارٍ الحفظ...":"Saving..."):(editing?(rtl?"حفظ التعديلات":"Save changes"):(rtl?"إضافة وحفظ":"Add and save"))}</button></div></aside></div>;
}

