  approvals:[{key:"managerApproval",ar:"اعتماد المدير المباشر",en:"Manager approval",type:"toggle"},{key:"hrApproval",ar:"اعتماد الموارد البشرية",en:"HR approval",type:"toggle"},{key:"expenseLimit",ar:"حد المصروف لاعتماد إضافي",en:"Extra approval expense threshold",type:"number"}],
  notifications:[{key:"emailEnabled",ar:"إشعارات البريد الإلكتروني",en:"Email notifications",type:"toggle"},{key:"inAppEnabled",ar:"الإشعارات داخل النظام",en:"In-app notifications",type:"toggle"},{key:"dailyDigest",ar:"الملخص اليومي",en:"Daily digest",type:"toggle"},{key:"senderName",ar:"اسم المرسل",en:"Sender name"}],
  locale:[{key:"defaultLanguage",ar:"اللغة الافتراضية",en:"Default language",type:"select",options:[{value:"ar",ar:"العربية",en:"Arabic"},{value:"en",ar:"الإنجليزية",en:"English"}]},{key:"timezone",ar:"المنطقة الزمنية",en:"Time zone",type:"select",options:[{value:"Asia/Riyadh",ar:"الرياض (UTC+3)",en:"Riyadh (UTC+3)"},{value:"Africa/Cairo",ar:"القاهرة",en:"Cairo"}]},{key:"dateFormat",ar:"تنسيق التاريخ",en:"Date format",type:"select",options:[{value:"DD/MM/YYYY",ar:"يوم/شهر/سنة",en:"DD/MM/YYYY"},{value:"YYYY-MM-DD",ar:"سنة-شهر-يوم",en:"YYYY-MM-DD"}]}],
  security:[{key:"sessionMinutes",ar:"مدة الجلسة بالدقائق",en:"Session timeout (minutes)",type:"number"},{key:"passwordExpiryDays",ar:"انتهاء كلمة المرور بعد أيام",en:"Password expiry (days)",type:"number"},{key:"auditRetentionDays",ar:"مدة الاحتفاظ بسجل التدقيق (90 يومًا على الأقل)",en:"Audit retention (minimum 90 days)",type:"number"}],
