const BANK_EXPORT_FIELDS=[{value:"employee_code",ar:"الرقم الوظيفي",en:"Employee code"},{value:"name_en",ar:"الاسم (إنجليزي)",en:"Name (English)"},{value:"name_ar",ar:"الاسم (عربي)",en:"Name (Arabic)"},{value:"bank_name",ar:"اسم البنك",en:"Bank name"},{value:"bank_account_number",ar:"رقم الحساب",en:"Account number"},{value:"bank_iban",ar:"الآيبان",en:"IBAN"},{value:"net_salary",ar:"صافي الراتب",en:"Net salary"}];

export function BankExportLayoutDrawer({rtl,initialColumns,close,submit}:{rtl:boolean;initialColumns:{field:string;header:string}[];close:()=>void;submit:(columns:{field:string;header:string}[])=>Promise<void>}){
  const [columns,setColumns]=useState(initialColumns.length?initialColumns:BANK_EXPORT_FIELDS.map(f=>({field:f.value,header:rtl?f.ar:f.en})));
  const [saving,setSaving]=useState(false),[error,setError]=useState("");
  const update=(index:number,patch:Partial<{field:string;header:string}>)=>setColumns(current=>current.map((c,i)=>i===index?{...c,...patch}:c));
  const add=()=>setColumns(current=>[...current,{field:"employee_code",header:""}]);
  const remove=(index:number)=>setColumns(current=>current.filter((_,i)=>i!==index));
  const save=async()=>{if(!columns.length){setError(rtl?"أضف عموداً واحداً على الأقل":"Add at least one column");return;}try{setSaving(true);setError("");await submit(columns);}catch(e){setError(e instanceof Error?e.message:(rtl?"تعذر حفظ إعدادات التصدير":"Unable to save export layout"));setSaving(false);}};
  return <div className="modal-layer" onMouseDown={event=>{if(event.target===event.currentTarget)close();}}><aside className="drawer bank-export-drawer" role="dialog" aria-modal="true"><header><div><span className="eyebrow">{rtl?"تصدير البنك":"BANK EXPORT"}</span><h2>{rtl?"إعداد أعمدة ملف التحويل البنكي":"Configure bank transfer column layout"}</h2></div><button className="icon-button" onClick={close} aria-label={rtl?"إغلاق":"Close"}><X size={20}/></button></header>
  <div className="allowance-editor"><header><b>{rtl?"الأعمدة":"Columns"}</b><button type="button" className="outline small" onClick={add}><Plus size={14}/>{rtl?"إضافة عمود":"Add column"}</button></header>
  {columns.map((column,index)=><div className="allowance-row" key={index}><select value={column.field} onChange={e=>update(index,{field:e.target.value})}>{BANK_EXPORT_FIELDS.map(f=><option value={f.value} key={f.value}>{rtl?f.ar:f.en}</option>)}</select><input value={column.header} placeholder={rtl?"عنوان العمود":"Column header"} onChange={e=>update(index,{header:e.target.value})}/><button type="button" className="icon-button" onClick={()=>remove(index)} aria-label={rtl?"حذف العمود":"Remove column"}><Trash2 size={16}/></button></div>)}
  </div>
  {error&&<div className="error-banner">{error}</div>}<footer><button type="button" className="outline" onClick={close}>{rtl?"إلغاء":"Cancel"}</button><button className="primary" disabled={saving} onClick={()=>void save()}><Check size={16}/>{saving?(rtl?"جارٍ الحفظ...":"Saving..."):(rtl?"حفظ":"Save")}</button></footer></aside></div>;
}
